import React, { useState } from "react";
import {
  TextField,
  Button,
  Grid,
  Typography,
  Box,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  CircularProgress,
  Snackbar,
  Alert,
  Link,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
} from "@mui/material";
import apiCall from "../../api";
import { useUserData } from "../../UserContext";

const CustomInvoiceGenerator = () => {
  const { userData } = useUserData();
  const [invoiceData, setInvoiceData] = useState({
    customerName: "",
    customerDetails: "",
    items: [],
    dueDate: "",
    tax: 0,
    discount: 0,
    invoiceNumber: "YG-",
    dateOfInvoice: "",
  });
  const [newItem, setNewItem] = useState({
    productService: "",
    quantity: 0,
    price: 0,
  });
  const [loading, setLoading] = useState(false);
  const [snackbar, setSnackbar] = useState({
    open: false,
    message: "",
    severity: "info",
  });
  const [generatedInvoiceUrl, setGeneratedInvoiceUrl] = useState(null);
  const [duplicateDialogOpen, setDuplicateDialogOpen] = useState(false);

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setInvoiceData({ ...invoiceData, [name]: value });
  };

  const handleItemChange = (e) => {
    const { name, value } = e.target;
    setNewItem({ ...newItem, [name]: value });
  };

  const addItem = () => {
    if (newItem.productService && newItem.quantity > 0 && newItem.price > 0) {
      setInvoiceData({
        ...invoiceData,
        items: [
          ...invoiceData.items,
          { ...newItem, total: newItem.quantity * newItem.price },
        ],
      });
      setNewItem({ productService: "", quantity: 0, price: 0 });
    }
  };

  const removeItem = (index) => {
    const updatedItems = invoiceData.items.filter((_, i) => i !== index);
    setInvoiceData({ ...invoiceData, items: updatedItems });
  };

  const calculateTotal = () => {
    const subtotal = invoiceData.items.reduce(
      (sum, item) => sum + item.total,
      0,
    );
    const taxAmount = subtotal * (invoiceData.tax / 100);
    const discountAmount = subtotal * (invoiceData.discount / 100);
    return subtotal + taxAmount - discountAmount;
  };

  const formatEuro = (amount) => {
    return new Intl.NumberFormat("de-DE", {
      style: "currency",
      currency: "EUR",
    }).format(amount);
  };

  const getResponseErrorMessage = (response, fallbackMessage) => {
    if (!response || typeof response !== "object") {
      return fallbackMessage;
    }

    return response.message || response.error || fallbackMessage;
  };

  const checkDuplicateInvoice = async () => {
    try {
      const response = await apiCall(
        "accounting_script",
        "checkDuplicateInvoiceNumber",
        {
          invoiceNumber: invoiceData.invoiceNumber,
          type: "YG",
          googleToken: userData.googleToken,
          username: userData.username,
        },
      );

      if (typeof response !== "boolean") {
        throw new Error(
          getResponseErrorMessage(
            response,
            "Unexpected response while checking duplicate invoice number",
          ),
        );
      }

      return response;
    } catch (error) {
      console.error("Error checking duplicate:", error);
      setSnackbar({
        open: true,
        message: error?.message || "Failed to check duplicate invoice number",
        severity: "error",
      });
      return null;
    }
  };

  const generateInvoice = async (skipDuplicateCheck = false) => {
    setLoading(true);
    try {
      // Check for duplicates first (unless skipped)
      if (!skipDuplicateCheck) {
        const isDuplicate = await checkDuplicateInvoice();
        if (isDuplicate === null) {
          return;
        }
        if (isDuplicate) {
          setDuplicateDialogOpen(true);
          setLoading(false);
          return;
        }
      }

      const formData = {
        customerName: invoiceData.customerName,
        customerDetails: invoiceData.customerDetails,
        dueDate: invoiceData.dueDate,
        productItems: invoiceData.items,
        tax: invoiceData.tax,
        discount: invoiceData.discount,
        type: "YG",
      };

      if (invoiceData.invoiceNumber) {
        formData.invoiceNumber = invoiceData.invoiceNumber;
      }

      if (invoiceData.dateOfInvoice) {
        formData.dateOfInvoice = invoiceData.dateOfInvoice;
      }

      const response = await apiCall("accounting_script", "generateInvoice", {
        data: formData,
        googleToken: userData.googleToken,
        username: userData.username,
      });

      if (response?.success === false) {
        throw new Error(
          getResponseErrorMessage(response, "Failed to generate invoice"),
        );
      }

      if (response && response.pdfUrl && response.message) {
        setGeneratedInvoiceUrl(response.pdfUrl);
        setSnackbar({
          open: true,
          message: response.message,
          severity: "success",
        });
        // Reset form after successful generation
        setInvoiceData({
          customerName: "",
          customerDetails: "",
          items: [],
          dueDate: "",
          tax: 0,
          discount: 0,
          invoiceNumber: "YG-",
          dateOfInvoice: "",
        });
      } else {
        throw new Error("Invalid response format");
      }
    } catch (error) {
      console.error("Failed to generate invoice", error);
      setSnackbar({
        open: true,
        message: `Failed to generate invoice: ${error.message}`,
        severity: "error",
      });
    } finally {
      setLoading(false);
    }
  };

  const handleProceedWithDuplicate = () => {
    setDuplicateDialogOpen(false);
    generateInvoice(true);
  };

  const handleCloseSnackbar = (event, reason) => {
    if (reason === "clickaway") return;
    setSnackbar({ ...snackbar, open: false });
  };

  return (
    <Box sx={{ p: 3 }}>
      <Typography variant="h5" gutterBottom>
        Custom Invoice Generator
      </Typography>
      <Grid container spacing={3}>
        <Grid item xs={12} sm={6}>
          <TextField
            fullWidth
            label="Customer Name"
            name="customerName"
            value={invoiceData.customerName}
            onChange={handleInputChange}
          />
        </Grid>
        <Grid item xs={12} sm={6}>
          <TextField
            fullWidth
            label="Customer Details"
            name="customerDetails"
            value={invoiceData.customerDetails}
            onChange={handleInputChange}
            multiline
            rows={4}
          />
        </Grid>
        <Grid item xs={12} sm={6}>
          <TextField
            fullWidth
            type="date"
            label="Due Date"
            name="dueDate"
            value={invoiceData.dueDate}
            onChange={handleInputChange}
            InputLabelProps={{ shrink: true }}
          />
        </Grid>
        <Grid item xs={12} sm={6}>
          <TextField
            fullWidth
            label="Invoice Number"
            name="invoiceNumber"
            value={invoiceData.invoiceNumber}
            onChange={handleInputChange}
            helperText="Default prefix is YG-. You can change it if needed."
          />
        </Grid>
        <Grid item xs={12} sm={6}>
          <TextField
            fullWidth
            type="date"
            label="Date of Invoice"
            name="dateOfInvoice"
            value={invoiceData.dateOfInvoice}
            onChange={handleInputChange}
            InputLabelProps={{ shrink: true }}
          />
        </Grid>
      </Grid>

      <Box sx={{ mt: 4, mb: 2 }}>
        <Typography variant="h6">Add Item</Typography>
        <Grid container spacing={2}>
          <Grid item xs={12} sm={4}>
            <TextField
              fullWidth
              label="Product/Service"
              name="productService"
              value={newItem.productService}
              onChange={handleItemChange}
            />
          </Grid>
          <Grid item xs={12} sm={3}>
            <TextField
              fullWidth
              label="Quantity"
              name="quantity"
              type="number"
              value={newItem.quantity}
              onChange={handleItemChange}
            />
          </Grid>
          <Grid item xs={12} sm={3}>
            <TextField
              fullWidth
              label="Price (€)"
              name="price"
              type="number"
              value={newItem.price}
              onChange={handleItemChange}
              InputProps={{
                startAdornment: <Typography sx={{ mr: 1 }}>€</Typography>,
              }}
            />
          </Grid>
          <Grid item xs={12} sm={2}>
            <Button
              variant="contained"
              onClick={addItem}
              fullWidth
              sx={{ height: "56px" }}
            >
              Add
            </Button>
          </Grid>
        </Grid>
      </Box>

      <TableContainer component={Paper} sx={{ mt: 4 }}>
        <Table>
          <TableHead>
            <TableRow>
              <TableCell>Product/Service</TableCell>
              <TableCell align="right">Quantity</TableCell>
              <TableCell align="right">Price</TableCell>
              <TableCell align="right">Total</TableCell>
              <TableCell align="right">Action</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {invoiceData.items.map((item, index) => (
              <TableRow key={index}>
                <TableCell>{item.productService}</TableCell>
                <TableCell align="right">{item.quantity}</TableCell>
                <TableCell align="right">{formatEuro(item.price)}</TableCell>
                <TableCell align="right">{formatEuro(item.total)}</TableCell>
                <TableCell align="right">
                  <Button onClick={() => removeItem(index)} color="secondary">
                    Remove
                  </Button>
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </TableContainer>

      <Grid container spacing={3} sx={{ mt: 4 }}>
        <Grid item xs={12} sm={6}>
          <TextField
            fullWidth
            label="Tax (%)"
            name="tax"
            type="number"
            value={invoiceData.tax}
            onChange={handleInputChange}
          />
        </Grid>
        <Grid item xs={12} sm={6}>
          <TextField
            fullWidth
            label="Discount (%)"
            name="discount"
            type="number"
            value={invoiceData.discount}
            onChange={handleInputChange}
          />
        </Grid>
      </Grid>

      <Typography variant="h6" sx={{ mt: 4 }}>
        Total: {formatEuro(calculateTotal())}
      </Typography>

      <Button
        variant="contained"
        onClick={() => generateInvoice(false)}
        sx={{ mt: 4 }}
        disabled={loading || invoiceData.items.length === 0}
      >
        {loading ? <CircularProgress size={24} /> : "Generate Invoice"}
      </Button>

      {generatedInvoiceUrl && (
        <Box sx={{ mt: 2 }}>
          <Typography variant="body1">
            Invoice generated successfully.{" "}
            <Link
              href={generatedInvoiceUrl}
              target="_blank"
              rel="noopener noreferrer"
            >
              View Invoice
            </Link>
          </Typography>
        </Box>
      )}

      {/* Duplicate Warning Dialog */}
      <Dialog
        open={duplicateDialogOpen}
        onClose={() => setDuplicateDialogOpen(false)}
      >
        <DialogTitle>Duplicate Invoice Number</DialogTitle>
        <DialogContent>
          <Alert severity="warning" sx={{ mb: 2 }}>
            An invoice with number "{invoiceData.invoiceNumber}" already exists.
          </Alert>
          <Typography>
            You can change the invoice number or proceed with the duplicate.
          </Typography>
          <TextField
            fullWidth
            label="Invoice Number"
            value={invoiceData.invoiceNumber}
            onChange={(e) =>
              setInvoiceData({ ...invoiceData, invoiceNumber: e.target.value })
            }
            sx={{ mt: 2 }}
          />
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setDuplicateDialogOpen(false)}>Cancel</Button>
          <Button
            onClick={handleProceedWithDuplicate}
            variant="contained"
            color="warning"
          >
            Proceed Anyway
          </Button>
          <Button
            onClick={() => {
              setDuplicateDialogOpen(false);
              generateInvoice(false);
            }}
            variant="contained"
          >
            Retry with New Number
          </Button>
        </DialogActions>
      </Dialog>

      <Snackbar
        open={snackbar.open}
        autoHideDuration={6000}
        onClose={handleCloseSnackbar}
      >
        <Alert
          onClose={handleCloseSnackbar}
          severity={snackbar.severity}
          sx={{ width: "100%" }}
        >
          {snackbar.message}
        </Alert>
      </Snackbar>
    </Box>
  );
};

export default CustomInvoiceGenerator;
