import React, { useEffect, useState } from "react";
import {
  Container,
  Typography,
  Box,
  Tabs,
  Tab,
  useMediaQuery,
  useTheme,
  ThemeProvider,
  createTheme,
} from "@mui/material";
import ShopifyTab from "./tabs/ShopifyTab";
import CardmarketTab from "./tabs/CardmarketTab";
import CustomTab from "./tabs/CustomTab";
import OutgoingTab from "./tabs/OutgoingTab";
import AllInvoicesTab from "./tabs/AllInvoicesTab";

// The old nested dark theme also carried layout rules this section depends on
// (single-line table cells, tighter cell padding, 4px button margin). Colors now
// come from the app theme, but these structural overrides are kept - applied as
// a nested theme (not CSS on a wrapper) so they also reach dialogs, which render
// in a portal outside this subtree.
const withAccountingLayout = (outerTheme) =>
  createTheme(outerTheme, {
    components: {
      MuiButton: { styleOverrides: { root: { margin: "4px" } } },
      MuiTableCell: {
        styleOverrides: { root: { whiteSpace: "nowrap", padding: "8px 16px" } },
      },
    },
  });

const TabPanel = ({ children, value, index, ...other }) => (
  <div
    role="tabpanel"
    hidden={value !== index}
    id={`accounting-tabpanel-${index}`}
    aria-labelledby={`accounting-tab-${index}`}
    {...other}
  >
    {value === index && <Box sx={{ pt: 3 }}>{children}</Box>}
  </div>
);

const AccountingSystem = ({ onMaxWidthChange }) => {
  const [mainTab, setMainTab] = useState(0);
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down("sm"));

  useEffect(() => {
    // Make the dialog wider for Accounting by default
    if (typeof onMaxWidthChange === "function") {
      onMaxWidthChange("lg");
      return () => onMaxWidthChange("md");
    }
    return undefined;
  }, [onMaxWidthChange]);

  const handleMainTabChange = (event, newValue) => {
    setMainTab(newValue);
  };

  return (
    <ThemeProvider theme={withAccountingLayout}>
    <Container maxWidth="xl">
      <Box sx={{ my: 4 }}>
        <Typography variant="h2" component="h1" gutterBottom>
          Accounting System
        </Typography>

        <Box sx={{ borderBottom: 1, borderColor: "divider" }}>
          <Tabs
            value={mainTab}
            onChange={handleMainTabChange}
            variant={isMobile ? "scrollable" : "standard"}
            scrollButtons={isMobile ? "auto" : false}
            aria-label="accounting tabs"
          >
            <Tab label="Shopify" />
            <Tab label="Cardmarket" />
            <Tab label="Custom" />
            <Tab label="Outgoing/Labour" />
            <Tab label="All" />
          </Tabs>
        </Box>

        <TabPanel value={mainTab} index={0}>
          <ShopifyTab onMaxWidthChange={onMaxWidthChange} />
        </TabPanel>

        <TabPanel value={mainTab} index={1}>
          <CardmarketTab onMaxWidthChange={onMaxWidthChange} />
        </TabPanel>

        <TabPanel value={mainTab} index={2}>
          <CustomTab onMaxWidthChange={onMaxWidthChange} />
        </TabPanel>

        <TabPanel value={mainTab} index={3}>
          <OutgoingTab onMaxWidthChange={onMaxWidthChange} />
        </TabPanel>

        <TabPanel value={mainTab} index={4}>
          <AllInvoicesTab onMaxWidthChange={onMaxWidthChange} />
        </TabPanel>
      </Box>
    </Container>
    </ThemeProvider>
  );
};

export default AccountingSystem;
